import vue from '@vitejs/plugin-vue'
import vueI18n from '@intlify/unplugin-vue-i18n/vite'
import vuetify, { transformAssetUrls } from 'vite-plugin-vuetify'
import { defineConfig, loadEnv } from 'vite'
import { fileURLToPath, URL } from 'node:url'
import { commonjsDeps } from '@koumoul/vjsf/utils/build.js'
import { settingsPath } from '@data-fair/lib-vuetify/vite.js'

export default defineConfig(({ mode }) => {
  // the ports come from the .env generated by df-dev-env: Vite does not fill process.env from it
  const env = loadEnv(mode, process.cwd(), '')
  const port = Number(env.APP_PORT ?? 3000)
  return {
    // `||`, not `??`: the e2e webServer runs Vite with an empty PUBLIC_URL
    base: env.PUBLIC_URL || '/app/',
    plugins: [
      vue({
        template: { transformAssetUrls }
      }),
      vueI18n({}),
      vuetify({
        autoImport: true,
        styles: {
          configFile: settingsPath
        }
      })
    ],
    resolve: {
      alias: {
        '@': fileURLToPath(new URL('./src', import.meta.url))
      },
      extensions: ['.js', '.json', '.jsx', '.mjs', '.ts', '.tsx', '.vue']
    },
    server: {
      port,
      strictPort: !!env.APP_PORT,
      // hmr follows the server port: a websocket left on 3000 would hold a second port
      hmr: { port, protocol: 'ws' },
      // without it the module graph is only transformed on the first request,
      // and the e2e suite races against that cold start
      warmup: { clientFiles: ['./src/main.ts', './src/**/*.vue'] }
    },
    optimizeDeps: {
      include: commonjsDeps
    }
  }
})
